import{_ as a,o as t,c as o,a2 as s}from"./chunks/framework.EUByU7Iq.js";const d=JSON.parse('{"title":"七虞","description":"","frontmatter":{"title":"七虞","date":"2026-11-17T00:00:00.000Z","seq":7,"categories":["美文","声律启蒙"],"collection":"《声律启蒙 · 上卷》","tags":["声律启蒙","清"],"poem":true,"poem_quote":false,"author":"佚名","source_book":"声律启蒙"},"headers":[],"relativePath":"blogs/声律启蒙·上卷/七虞.md","filePath":"blogs/声律启蒙·上卷/七虞.md"}'),r={name:"blogs/声律启蒙·上卷/七虞.md"};function p(l,e,_,c,n,i){return t(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="七虞" tabindex="-1">七虞 <a class="header-anchor" href="#七虞" aria-label="Permalink to &quot;七虞&quot;">​</a></h1><p class="poem-meta">清 · 佚名　·　上卷</p><div class="poem"><p class="poem-stanza">金对玉，宝对珠，玉兔对金乌。孤舟对短棹，一雁对双凫。横醉眼，捻吟须，李白对杨朱。秋霜多过雁，夜月有啼乌。日暧园林花易赏，雪寒村舍酒难沽。人处岭南，善探巨象口中齿；客居江右，偶夺骊龙颔下珠。</p><p class="poem-stanza">贤对圣，智对愚，傅粉对施朱。名缰对利锁，挈榼对提壶。鸠哺子，燕调雏，石帐对郇厨。烟轻笼岸柳，风急撼庭梧。鸜眼一方端石砚，龙涎三炷博山垆。曲沼鱼多，可使渔人结网；平田兔少，漫劳耕者守株。</p><p class="poem-stanza">秦对赵，越对吴，钓客对耕夫。箕裘对杖履，杞梓对桑榆。天欲晓，日将晡，狡兔对妖狐。读书甘刺股，煮粥惜焚须。韩信武能平四海，左思文足赋三都。嘉遁幽人，适志竹篱茅舍；胜游公子，玩情柳陌花衢。</p></div>',3)])])}const u=a(r,[["render",p]]);export{d as __pageData,u as default};
